namespace fs=std::filesystem;
namespace saiv {
static double now(){return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();}
static std::string utf8(const fs::path& p){return p.u8string();}
static fs::path userFolder(){wchar_t p[32768]{};DWORD n=GetEnvironmentVariableW(L"LOCALAPPDATA",p,32768);return (n&&n<32768?fs::path(p):fs::temp_directory_path())/L"SAIV"/L"InstrumentStudio";}
static void writeFile(const fs::path& p,const std::string& s){std::ofstream f(p,std::ios::binary|std::ios::trunc);if(!f)throw std::runtime_error("Cannot create file: "+utf8(p));f.write(s.data(),static_cast<std::streamsize>(s.size()));f.close();if(!f)throw std::runtime_error("Writing failed: "+utf8(p));}
static std::string readFile(const fs::path& p){if(fs::file_size(p)>64*1024*1024)throw std::runtime_error("File exceeds 64 MiB. Split it before importing.");std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("Cannot open file: "+utf8(p));return {std::istreambuf_iterator<char>(f),{}};}
static void paragraph(const char* text){ImGui::PushTextWrapPos(0);ImGui::TextUnformatted(text);ImGui::PopTextWrapPos();}
static void muted(const char* text){ImGui::TextColored(ImVec4(.54f,.63f,.72f,1),"%s",text);}
static bool button(const char* label,ImVec2 size=ImVec2(0,0)){return ImGui::Button(label,size);}
static void title(const char* text,ImFont* font){if(font)ImGui::PushFont(font);ImGui::TextUnformatted(text);if(font)ImGui::PopFont();}
App::App(HWND w,ImFont* h,ImFont* m,bool useDemo,const fs::path& testWire):window_(w),heading_(h),mono_(m){if(!testWire.empty())testWire_.open(testWire,std::ios::binary|std::ios::trunc);protocol_.send=[this](const std::string& s){if(testWire_.is_open()){testWire_<<s;testWire_.flush();}else send(s);};ports_=enumeratePorts();if(!ports_.empty()){settings_.port=ports_[0].name;strncpy_s(portName_,settings_.port.c_str(),_TRUNCATE);}try{std::ifstream f(userFolder()/"settings.txt");std::string p;unsigned baud;int parity,bits;if(f>>p>>baud>>parity>>bits){if(p.rfind("COM",0)==0&&p.size()<16)strncpy_s(portName_,p.c_str(),_TRUNCATE);if(baud>=1200&&baud<=115200)settings_.baud=baud;if(parity>=0&&parity<=2)settings_.parity=parity;if(bits==7||bits==8)settings_.bits=bits;}}catch(...){}const unsigned rates[]={1200,2400,4800,9600,19200,38400,57600,115200};for(int i=0;i<8;i++)if(rates[i]==settings_.baud)baudIndex_=i;if(useDemo)demo();}
App::~App(){if(settingFuture_.valid())settingFuture_.wait();serial_.disconnect();if(testWire_.is_open()||demo_)return;try{fs::create_directories(userFolder());writeFile(userFolder()/"settings.txt",std::string(portName_)+" "+std::to_string(settings_.baud)+" "+std::to_string(settings_.parity)+" "+std::to_string(settings_.bits));}catch(...){} }
Table* App::selected(){if(documents_.empty())return nullptr;document_=std::clamp(document_,0,static_cast<int>(documents_.size())-1);return &documents_[document_].table;}
void App::autoMap(){if(auto* t=selected()){auto find=[&](std::initializer_list<const char*> aliases){for(auto n:aliases){int c=t->column(n);if(c>=0)return c;}return -1;};auto& d=documents_[document_];d.y=find({"T","Temp","Temperature"});if(d.y<0&&!t->columns.empty())d.y=0;d.x=-1;utilCol_=d.y;rangeFirst_=1;rangeLast_=static_cast<int>(t->rows.size());calc_.temperature=d.y;calc_.pressure=find({"P","Press","Pressure"});calc_.conductivity=find({"C","Cond.","Conductivity"});calc_.salinity=find({"S","Sal.","Salinity"});calc_.oxygen=find({"OX","Ox %"});preview_.reset();}}
void App::addDocument(Table t){if(t.rows.empty()){error_="No supported measurement rows found. Use CTD N rows, FIELDS logger files or a table with named columns.";return;}if(documents_.size()>=12){error_="Close a dataset before opening another (12 maximum).";return;}notice_="Loaded "+std::to_string(t.rows.size())+" rows, "+std::to_string(t.columns.size())+" columns";if(t.rejected)notice_+="; "+std::to_string(t.rejected)+" malformed rows rejected";documents_.push_back({std::move(t)});document_=static_cast<int>(documents_.size())-1;autoMap();updateDocument();}
void App::demo(){disconnect();demo_=true;addDocument(demoProfile());live_.reset();live_.table=demoProfile();terminal_.clear();log("DEMO","Synthetic measurements. No serial port is open.");log("RX","OSU107 Instrument logger SN107, Ver: demonstration");log("RX","Hold <I> to wake instrument");notice_="Synthetic demonstration. Connect a port to work with a real instrument.";page_=1;focusTerminal_=true;}
void App::log(const std::string& d,const std::string& text){SYSTEMTIME t;GetLocalTime(&t);char b[32];sprintf_s(b,"%02u:%02u:%02u.%03u  ",t.wHour,t.wMinute,t.wSecond,t.wMilliseconds);terminal_.push_back(std::string(b)+d+"  "+text);while(terminal_.size()>18000)terminal_.pop_front();}
void App::acceptRx(const std::string& text){rxBytes_+=text.size();if(record_.is_open()){record_.write(text.data(),static_cast<std::streamsize>(text.size()));record_.flush();if(!record_){error_="Recording failed. Check free disk space.";record_.close();}}live_.feed(text);protocol_.ingest(text,now());for(unsigned char c:text){if(c=='\r')continue;if(c=='\n'){log("RX",terminalPartial_);terminalPartial_.clear();}else if(c=='\t'||c>=32)terminalPartial_+=c;else{char b[8];sprintf_s(b,"<%02X>",c);terminalPartial_+=b;}if(terminalPartial_.size()>8192){log("RX",terminalPartial_);terminalPartial_.clear();}}}
bool App::terminalCharacter(unsigned character){
 if(settingBusy_||page_!=1||GetForegroundWindow()!=window_||ImGui::GetIO().WantTextInput||ImGui::IsPopupOpen(nullptr,ImGuiPopupFlags_AnyPopupId|ImGuiPopupFlags_AnyPopupLevel))return false;
 if(character>127){error_="Instrument terminal accepts ASCII characters.";return true;}
 if(!serial_.connected&&!testWire_.is_open()){notice_="Use Autodetect or Connect before typing to the instrument.";return true;}
 protocol_.typeCharacters(std::string(1,static_cast<char>(character)),now());return true;
}
void App::send(const std::string& text){if(!serial_.connected){error_="No serial connection is open.";return;}serial_.write(text);}
void App::connect(){if(detector_.busy){error_="Wait for discovery to finish.";return;}settings_.port=trim(portName_);if(settings_.port.empty()){error_="Choose a COM port.";return;}demo_=false;connectionWanted_=true;connecting_=true;protocol_.connected();live_.reset();serial_.connect(settings_);notice_="Opening "+settings_.port+"...";}
void App::disconnect(){downloadWanted_=false;connectionWanted_=false;connecting_=false;acceptedInstrument_=false;serial_.disconnect();protocol_.disconnected();if(record_.is_open())record_.close();}
void App::poll(){
 if(settingBusy_){if(settingFuture_.wait_for(std::chrono::seconds(0))!=std::future_status::ready)return;auto result=settingFuture_.get();settingBusy_=false;protocol_.connected();protocol_.device=acceptedIdentity_;acceptRx(result.received);if(result.error.empty()){notice_=result.message;error_.clear();}else{error_=result.error;acceptedInstrument_=false;}return;}
 for(auto& e:serial_.poll()){if(e.kind==SerialEvent::Connected){connecting_=false;protocol_.connected();notice_="Connected to "+e.text+". Listening for identification.";if(acceptedInstrument_&&acceptedPort_==settings_.port)protocol_.device=acceptedIdentity_;}else if(e.kind==SerialEvent::Received)acceptRx(e.text);else if(e.kind==SerialEvent::Transmitted){txBytes_+=e.text.size();std::string s;for(unsigned char c:e.text){if(c>=32&&c<127)s+=c;else{char b[8];sprintf_s(b,"<%02X>",c);s+=b;}}if(showRawTraffic_)log("TX",s);}else if(e.kind==SerialEvent::Error){error_=e.text;}else if(e.kind==SerialEvent::Closed){connecting_=false;protocol_.disconnected();nextReconnect_=now()+2;}}
 if(serial_.connected||testWire_.is_open())protocol_.tick(now());if(downloadWanted_&&protocol_.operation==Protocol::Operation::Idle){downloadWanted_=false;if(protocol_.mainMenu||protocol_.device.logger)protocol_.receiveData(now());}if(connectionWanted_&&reconnect_&&!serial_.connected&&!connecting_&&!detector_.busy&&now()>=nextReconnect_){connecting_=true;serial_.connect(settings_);nextReconnect_=now()+2;}
 if(loading_&&loader_.wait_for(std::chrono::seconds(0))==std::future_status::ready){loading_=false;try{Table result=loader_.get();if(convertAfterLoad_){convertAfterLoad_=false;if(!convertDialog(window_,result))return;}addDocument(std::move(result));page_=2;dataView_=0;error_.clear();}catch(const std::exception& e){convertAfterLoad_=false;error_=e.what();}}
 if(copying_&&copier_.wait_for(std::chrono::seconds(0))==std::future_status::ready){copying_=false;try{notice_=copier_.get();}catch(const std::exception& e){error_=e.what();}}
 if(scanning_&&scanner_.wait_for(std::chrono::seconds(0))==std::future_status::ready){scanning_=false;try{diskFiles_=scanner_.get();diskSelected_.assign(diskFiles_.size(),false);notice_="Found "+std::to_string(diskFiles_.size())+" data files.";}catch(const std::exception& e){error_=e.what();}}}
fs::path App::fileDialog(bool save,const wchar_t* heading,const wchar_t* extension,const wchar_t* filter){wchar_t b[32768]{};OPENFILENAMEW o{};o.lStructSize=sizeof(o);o.hwndOwner=window_;o.lpstrFile=b;o.nMaxFile=32768;o.lpstrFilter=filter;o.lpstrTitle=heading;o.lpstrDefExt=extension;o.Flags=OFN_EXPLORER|OFN_NOCHANGEDIR|OFN_PATHMUSTEXIST|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);if(save?GetSaveFileNameW(&o):GetOpenFileNameW(&o))return b;return {};}
fs::path App::folderDialog(const wchar_t* heading){IFileDialog* d=nullptr;fs::path result;if(SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&d)))){DWORD options;d->GetOptions(&options);d->SetOptions(options|FOS_PICKFOLDERS|FOS_FORCEFILESYSTEM);d->SetTitle(heading);if(SUCCEEDED(d->Show(window_))){IShellItem* item=nullptr;if(SUCCEEDED(d->GetResult(&item))){PWSTR p=nullptr;if(SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH,&p))){result=p;CoTaskMemFree(p);}item->Release();}}d->Release();}return result;}
void App::loadFile(const fs::path& p){if(p.empty()||loading_)return;loading_=true;notice_="Reading "+utf8(p.filename())+"...";loader_=std::async(std::launch::async,[p]{return loadDataset(p);});}
void App::saveData(const std::string& data,const wchar_t* heading,const wchar_t* extension){auto p=fileDialog(true,heading,extension,wcscmp(extension,L"csv")==0?L"CSV measurements\0*.csv\0\0":L"Text files\0*.txt;*.log\0All files\0*.*\0\0");if(p.empty())return;try{writeFile(p,data);notice_="Saved "+utf8(p);}catch(const std::exception& e){error_=e.what();}}
bool App::columnPicker(const char* label,const Table& t,int& col,bool none){bool change=false;const char* p=col>=0&&col<static_cast<int>(t.columns.size())?t.columns[col].c_str():(none?"None / row number":"Choose column");if(ImGui::BeginCombo(label,p)){if(none&&ImGui::Selectable("None / row number",col<0)){col=-1;change=true;}for(size_t i=0;i<t.columns.size();i++)if(ImGui::Selectable(t.columns[i].c_str(),col==static_cast<int>(i))){col=static_cast<int>(i);change=true;}ImGui::EndCombo();}return change;}
void App::grid(const Table& t,float height){if(t.columns.empty()){muted("No measurement rows yet.");return;}int count=static_cast<int>(t.columns.size());if(ImGui::BeginTable("measurements",count,ImGuiTableFlags_ScrollX|ImGuiTableFlags_ScrollY|ImGuiTableFlags_RowBg|ImGuiTableFlags_BordersInnerH|ImGuiTableFlags_Resizable|ImGuiTableFlags_Hideable,ImVec2(0,height))){ImGui::TableSetupScrollFreeze(1,1);for(int c=0;c<count;c++)ImGui::TableSetupColumn(t.columns[c].c_str(),ImGuiTableColumnFlags_WidthFixed,115);ImGui::TableHeadersRow();ImGuiListClipper clip;clip.Begin(static_cast<int>(t.rows.size()));while(clip.Step())for(int i=clip.DisplayStart;i<clip.DisplayEnd;i++){ImGui::TableNextRow();for(int c=0;c<count;c++){ImGui::TableSetColumnIndex(c);const auto& v=t.rows[i][c];if(v.empty()||lower(v)=="nan")ImGui::TextDisabled("--");else ImGui::TextUnformatted(v.c_str());}}ImGui::EndTable();}}
void App::drawUtilities(){title("Measurement utilities",heading_);muted("Preview a result, then keep it as a new dataset. Your source stays intact.");Table* t=selected();if(!t){paragraph("Open a dataset first.");return;}ImGui::Text("Source: %s",t->source.c_str());ImGui::SetNextItemWidth(360);if(ImGui::Combo("Tool",&utility_,"SIT calculations\0Select / split rows\0Filter by value range\0Remove spikes (running median)\0Adjust values (gain + offset)\0Standard depths / pressure levels\0"))preview_.reset();ImGui::Separator();
 if(utility_==0){paragraph("Add salinity, sound velocity and density anomaly using the documented SIT routines and available C, T, P and S columns. Existing fields are retained. Use Data > Convert current dataset for unit choices, real depth, oxygen and PAR.");}
 else if(utility_==1){ImGui::SetNextItemWidth(150);ImGui::InputInt("First row (1-based)",&rangeFirst_);ImGui::SetNextItemWidth(150);ImGui::InputInt("Last row (inclusive)",&rangeLast_);}
 else{ImGui::SetNextItemWidth(270);columnPicker(utility_==5?"Depth / sea pressure":"Column",*t,utilCol_);if(utility_==2){ImGui::InputDouble("Minimum",&minimum_);ImGui::InputDouble("Maximum",&maximum_);}if(utility_==3){ImGui::InputInt("Window (samples)",&windowSize_);ImGui::InputDouble("Maximum deviation from median",&threshold_);paragraph("Outliers become missing in a new column. Original measurements remain unchanged.");}if(utility_==4){ImGui::InputDouble("Gain",&gain_);ImGui::InputDouble("Offset",&offset_);paragraph("New column = original * gain + offset. This does not write instrument calibration.");}if(utility_==5){ImGui::InputDouble("Level interval",&step_);ImGui::InputDouble("Maximum interpolation gap",&maxGap_);paragraph("Select one monotonic downcast or upcast first. No extrapolation; large gaps stay missing.");}}
 ImGui::BeginDisabled(false);if(button("Generate preview",ImVec2(185,32))){try{if(utility_==0){calc_.latitude=latitude_;calc_.longitude=longitude_;preview_=enrichSit(*t);}else if(utility_==1){if(rangeFirst_<1||rangeLast_<rangeFirst_||rangeLast_>static_cast<int>(t->rows.size()))throw std::runtime_error("Row selection is outside the dataset.");preview_=rangeRows(*t,rangeFirst_-1,rangeLast_);}else if(utility_==2){if(minimum_>maximum_)throw std::runtime_error("Minimum must not exceed maximum.");preview_=filterRange(*t,utilCol_,minimum_,maximum_);}else if(utility_==3)preview_=despike(*t,utilCol_,windowSize_,threshold_);else if(utility_==4)preview_=affine(*t,utilCol_,gain_,offset_);else preview_=standardDepths(*t,utilCol_,step_,maxGap_);preview_->source=t->source+" / derived";error_.clear();}catch(const std::exception& e){error_=e.what();preview_.reset();}}ImGui::EndDisabled();if(preview_){ImGui::SameLine();if(button("Keep as new dataset",ImVec2(200,32))){Table result=std::move(*preview_);preview_.reset();addDocument(std::move(result));page_=2;return;}ImGui::SameLine();if(button("Export preview"))saveData(preview_->csv(),L"Export derived measurements",L"csv");ImGui::Text("Preview: %zu rows, %zu columns",preview_->rows.size(),preview_->columns.size());grid(*preview_,std::max(120.f,ImGui::GetContentRegionAvail().y));}}
void App::drawLogger(){title("Logger files",heading_);muted("Copy measurements from the mounted logger disk to your computer.");paragraph("If the latest file is missing, stop logging on the instrument, request a disk refresh in Terminal, and wait for the disk to reappear. Copying here never deletes files from the logger.");ImGui::BeginDisabled(scanning_||copying_);if(button("Choose logger folder",ImVec2(210,34))){auto p=folderDialog(L"Select mounted logger disk or data folder");if(!p.empty()){disk_=p;diskFiles_.clear();diskSelected_.clear();}}ImGui::SameLine();if(button("Scan data files",ImVec2(170,34))&&!disk_.empty()){scanning_=true;auto root=disk_;scanner_=std::async(std::launch::async,[root]{std::vector<fs::path> files;std::error_code ec;for(fs::recursive_directory_iterator it(root,fs::directory_options::skip_permission_denied,ec),end;it!=end;it.increment(ec)){if(ec){ec.clear();continue;}if(it.depth()>5){it.disable_recursion_pending();continue;}if(it->is_symlink(ec)){it.disable_recursion_pending();continue;}auto ext=lower(it->path().extension().string());if(it->is_regular_file(ec)&&(ext==".txt"||ext==".csv"||ext==".log"||ext==".asc")){files.push_back(it->path());if(files.size()>=10000)break;}}std::sort(files.begin(),files.end());return files;});}ImGui::EndDisabled();if(!disk_.empty())paragraph(utf8(disk_).c_str());if(scanning_)muted("Scanning in background...");if(copying_)muted("Copying and verifying file sizes...");if(button("Select all"))std::fill(diskSelected_.begin(),diskSelected_.end(),true);ImGui::SameLine();if(button("Clear selection"))std::fill(diskSelected_.begin(),diskSelected_.end(),false);ImGui::SameLine();ImGui::BeginDisabled(copying_||scanning_||std::none_of(diskSelected_.begin(),diskSelected_.end(),[](bool b){return b;}));
 if(button("Copy selected files")){auto target=folderDialog(L"Select destination on your computer");if(!target.empty()){std::vector<fs::path> files;for(size_t i=0;i<diskFiles_.size();i++)if(diskSelected_[i])files.push_back(diskFiles_[i]);auto root=disk_;copying_=true;copier_=std::async(std::launch::async,[root,target,files]{size_t copied=0;for(auto& from:files){auto relative=fs::relative(from,root);if(relative.empty()||relative.is_absolute()||relative.string().find("..")!=std::string::npos)throw std::runtime_error("Unexpected source path.");auto to=target/relative;fs::create_directories(to.parent_path());if(fs::exists(to)){int suffix=1;auto base=to;do{to=base.parent_path()/(base.stem().wstring()+L"_copy"+std::to_wstring(suffix++)+base.extension().wstring());}while(fs::exists(to));}fs::copy_file(from,to,fs::copy_options::none);if(fs::file_size(from)!=fs::file_size(to))throw std::runtime_error("Copy verification failed: "+utf8(to));copied++;}return "Copied "+std::to_string(copied)+" files. Existing files were not overwritten.";});}}ImGui::EndDisabled();ImGui::BeginChild("files",ImVec2(0,0),ImGuiChildFlags_Borders);for(size_t i=0;i<diskFiles_.size();i++){ImGui::PushID(static_cast<int>(i));bool checked=diskSelected_[i];if(ImGui::Checkbox("##selected",&checked))diskSelected_[i]=checked;ImGui::SameLine();std::error_code ec;auto rel=fs::relative(diskFiles_[i],disk_,ec);if(ImGui::Selectable(utf8(ec?diskFiles_[i]:rel).c_str(),false,ImGuiSelectableFlags_AllowDoubleClick)&&ImGui::IsMouseDoubleClicked(0))loadFile(diskFiles_[i]);ImGui::PopID();}ImGui::EndChild();}

}
